import json, jsonlines, sys

# Validate JSON files
for f in ['plan/plan.json','state/task_state.json','state/index.json']:
    with open(f) as fh: json.load(fh)
    print(f'✅ {f}')

# Validate JSONL files
for f in ['plan/command_plan.jsonl','logs/event_log.jsonl']:
    with open(f) as fh:
        for i,line in enumerate(fh,1):
            json.loads(line)
    print(f'✅ {f} ({i} lines)')

# Dependency integrity check
plan = json.load(open('plan/plan.json'))
ids = {s['id'] for s in plan['subtasks']}
for s in plan['subtasks']:
    for d in s['dependencies']:
        assert d in ids, f'Missing dep {d} in subtask {s[\"id\"]}'
print('✅ Dependency integrity OK')

# Cycle check (topo sort)
from collections import defaultdict, deque
graph = defaultdict(list)
indeg = defaultdict(int)
for s in plan['subtasks']:
    for d in s['dependencies']:
        graph[d].append(s['id'])
        indeg[s['id']] += 1
q = deque([i for i in ids if indeg[i]==0])
visited = 0
while q:
    n = q.popleft(); visited += 1
    for nb in graph[n]:
        indeg[nb] -= 1
        if indeg[nb]==0: q.append(nb)
assert visited == len(ids), 'Cycle detected!'
print('✅ No cycles')
"
